226	    /**
227	     * Whether the building queue will take this candidate on this planet right now.
228	     *
229	     * Public because "the building queue cannot answer this" is a question a second planner has to
230	     * ask: a planet that cannot buy capacity here has one other route, and the yard may only take it
231	     * when this says no. The gate itself stays in one place rather than being restated next to it.
232	     */
233	    public function canQueue(PlanetService $planet, BuildCandidate $candidate): bool
234	    {
235	        return $this->refusal($planet, $candidate) === null;
236	    }
237	
238	    /**
239	     * Which of the host's gates refuses this building here, or null when the planet can queue it.
240	     * The gates are asked in the order the building page asks them: planet type, free queue space,
241	     * met requirements, a balance it can pay and a field the building still fits in. Named, so a
242	     * planet that never builds says why instead of reading as idle.
243	     */
244	    public function refusal(PlanetService $planet, BuildCandidate $candidate): ?string
245	    {
246	        $object = ObjectService::getObjectById($candidate->buildingId);
247	        $machineName = $object->machine_name;
248	
249	        if (!ObjectService::objectValidPlanetType($machineName, $planet)) {
250	            return 'planet type';
251	        }
252	        if ($this->buildingQueueService->retrieveQueue($planet)->isQueueFull()) {
253	            return 'queue full';
254	        }
255	        // The host refuses an order for a station whose units are already in production, and the
256	        // executor asks the same gate (`QueueAiBuildingAction`). Not asked here, the pass offers a
257	        // step the executor then refuses: the planet spends its one step on a refusal, queues
258	        // nothing, and still reads buildable to the planner -- idle while called buildable (live:
259	        // player 44, 4 of 4 planets). Asking it here lets the planet fall through to its next
260	        // candidate instead.
261	        if ($planet->getPlayer()?->isObjectUpgradeBlocked($candidate->buildingId) === true) {
262	            return 'shipyard busy';
263	        }
264	        if (!ObjectService::objectRequirementsMetWithQueue($machineName, $planet->getObjectLevel($machineName) + 1, $planet)) {
265	            return 'requirements';
266	        }
267	        if (!$planet->hasResources($this->withReserve($planet, ObjectService::getObjectPrice($machineName, $planet), ReserveFloor::ECONOMY_HOURS))) {
268	            return 'price plus reserve';
269	        }
270	        // `BuildingQueueService::start()` refuses a field-consuming building once the planet's fields
271	        // are used up, and a terraformer cannot rescue it because a terraformer consumes a field too.
272	        if ($object->consumesPlanetField && $planet->getBuildingCount() >= $planet->getPlanetFieldMax()) {
273	            return 'no free field';
274	        }
275	
276	        return null;
277	    }
278	
279	    /**
280	     * What this planet is saving for: the price plus reserve of the first economy step the planet is
